enum class Effect : uint8_t { Default, Rhythm };
enum class State : uint8_t { Off, Now, FortyTwoHours, SevenDays, Unknown };
// Forecast pulses start on the shared clock and end at their state-specific duration.
inline bool forecastPhase(uint32_t now, uint16_t periodMs, State state, uint16_t& phase) {
  if (!periodMs) return false;
  uint16_t tenths = state == State::FortyTwoHours ? 7 : state == State::SevenDays ? 4 : 0;
  if (!tenths) return false;
  uint32_t duration = (static_cast<uint32_t>(periodMs) * tenths + 9U) / 10U;
  uint32_t elapsed = now % periodMs;
  if (elapsed >= duration) return false;
  phase = static_cast<uint16_t>(elapsed * 65536UL / duration);
  return true;
}
// Rhythm cycle uses the same elapsed time for every spot.
inline bool rhythmVisible(uint32_t cycleMs, uint32_t showMs, uint32_t tailMs, bool nearForecast) {
  return cycleMs < showMs || (nearForecast && cycleMs - showMs < tailMs);
}
// State brightness is relative to the configured controller brightness.
inline uint8_t brightnessPercent(State state) {
  switch (state) {
    case State::Now: return 80;
    case State::FortyTwoHours: return 50;
    case State::SevenDays: return 30;
    default: return 0;
  }
}
